getHistory.example:
(async () => {
  const h = await getHistory({ paths: 'navigation.speedOverGround:max', from: '2026-06-11T06:00:00Z', to: '2026-06-11T12:00:00Z', resolution: 300 });
  if (!h.available) return JSON.stringify({ note: h.error });
  const pts = h.values['navigation.speedOverGround'].filter(p => p.value != null);
  return JSON.stringify({ maxKn: (Math.max(...pts.map(p => p.value)) * 1.94384).toFixed(1) });
})()

getCourseStatus.example:
(async () => {
  const c = await getCourseStatus();
  if (!c.available) return JSON.stringify({ note: c.error });
  if (!c.navigating) return JSON.stringify({ navigating: false });
  return JSON.stringify({ distanceNm: (c.calcValues.distance / 1852).toFixed(2), bearingDeg: (c.calcValues.bearingTrue * 57.2958).toFixed(0) });
})()

