  if (!w.available) return JSON.stringify({ note: w.reason || w.error });
  const o = w.data[0] || {};
  return JSON.stringify({ airC: o.outside?.temperature == null ? null : (o.outside.temperature - 273.15).toFixed(1), windKn: o.wind?.speedTrue == null ? null : (o.wind.speedTrue * 1.94384).toFixed(1) });
