getRadarTargets.example:
(async () => {
  const r = await getRadarTargets();
  if (!r.available) return JSON.stringify({ note: r.reason || r.error });
  const dangerous = r.targets.filter(t => t.danger && t.danger.cpa < 500).map(t => ({ radar: t.radar_id, id: t.id, cpaM: t.danger.cpa, tcpaS: t.danger.tcpa }));
  return JSON.stringify({ count: r.count, devices: r.deviceStatus, dangerous });
})()

getTargets.example:
(async () => {
