anchor_watch.example:
(async () => {
  const cur = await getPathValue('navigation.anchor.currentRadius');
  const max = await getPathValue('navigation.anchor.maxRadius');
  const current = cur.data?.value ?? null;
  const limit = max.data?.value ?? null;
  if (current == null || limit == null) return JSON.stringify({ anchorWatch: false, note: 'no anchor watch set' });
  return JSON.stringify({ currentM: Math.round(current), maxM: Math.round(limit), dragging: current > limit, marginM: Math.round(limit - current) });
})()

cpa_tcpa.example:
(async () => {
  const v = await getVesselState();
  const sp = v.data['navigation.position']?.value;
  const scog = v.data['navigation.courseOverGroundTrue']?.value;
  const ssog = v.data['navigation.speedOverGround']?.value;
  if (!sp || scog == null || ssog == null) return JSON.stringify({ note: 'need self position, course and speed' });
  const t = await getTargets({ source: 'ais' });
  const D = Math.PI / 180, mLat = 111320, mLon = 111320 * Math.cos(sp.latitude * D);
  const sx = ssog * Math.sin(scog), sy = ssog * Math.cos(scog);
  const out = [];
  for (const tg of t.targets) {
    const p = tg['navigation.position']?.value;
    const cog = tg['navigation.courseOverGroundTrue']?.value;
    const sog = tg['navigation.speedOverGround']?.value;
    if (!p || cog == null || sog == null) continue;
    const rx = (p.longitude - sp.longitude) * mLon, ry = (p.latitude - sp.latitude) * mLat;
    const dvx = sog * Math.sin(cog) - sx, dvy = sog * Math.cos(cog) - sy;
    const v2 = dvx * dvx + dvy * dvy;
    let tcpa = v2 > 0 ? -(rx * dvx + ry * dvy) / v2 : 0;
    if (tcpa < 0) tcpa = 0;
    const cx = rx + dvx * tcpa, cy = ry + dvy * tcpa;
    out.push({ mmsi: tg.mmsi, cpaM: Math.round(Math.sqrt(cx * cx + cy * cy)), tcpaS: Math.round(tcpa), rangeM: Math.round(Math.sqrt(rx * rx + ry * ry)) });
  }
  out.sort((a, b) => a.cpaM - b.cpaM);
  return JSON.stringify({ closest: out.slice(0, 5) });
})()
